% Include necessary library for global constraints
include "globals.mzn";

% Decision variables: digits a, b, c, d
% Each digit is between 0 and 9
var 0..9: a;
var 0..9: b;
var 0..9: c;
var 0..9: d;

% Constraint: all digits are distinct
constraint all_different([a,b,c,d]);

% Define two-digit numbers as per problem statement
var 10*a + b: ab;
var 10*b + c: bc;
var 10*c + d: cd;
var 10*d + a: da;

% Constraint: cd = 3 * ab
constraint cd = 3 * ab;

% Constraint: da = 2 * bc
constraint da = 2 * bc;

% Solve for any solution satisfying the constraints
solve satisfy;

% Output the PIN digits as JSON
output [
    "{",
    join(",", [
        "\"" ++ "a" ++ "\": " ++ show(a),
        "\"" ++ "b" ++ "\": " ++ show(b),
        "\"" ++ "c" ++ "\": " ++ show(c),
        "\"" ++ "d" ++ "\": " ++ show(d)
    ]),
    "}"
];
```

