```minizinc
% Climbing stairs with steps between m1 and m2 (inclusive)
% We want to climb exactly n steps, using moves of size between m1 and m2
% After reaching the top, remaining moves are 0

include "globals.mzn";

int: n = 20;          % total steps to climb
int: m1 = 3;          % minimum steps per move
int: m2 = 5;          % maximum steps per move

% We consider at most n moves (worst case: all moves are 1 step, but here min step is 3, so n moves is safe upper bound)
% Each move is either 0 (no step, after reaching top) or between m1 and m2
array[1..n] of var 0..m2: steps;

% Constraint: sum of steps must be exactly n
constraint sum(i in 1..n)(steps[i]) == n;

% Constraint: if steps[i] > 0 then steps[i] >= m1
% So steps[i] in {0} or [m1..m2]
constraint forall(i in 1..n) (
    steps[i] == 0 \/ (steps[i] >= m1 /\ steps[i] <= m2)
);

% Once a zero step is taken, all subsequent steps must be zero (no moves after reaching top)
constraint forall(i in 1..n-1) (
    (steps[i] == 0) -> (steps[i+1] == 0)
);

solve satisfy;

output [
    "{",
    "\"steps\": [" ++ join(", ", [show(steps[i]) | i in 1..n]) ++ "]",
    "}"
];
```

