include "globals.mzn";

% We have 5 children, 5 ages, 5 countries, 5 stories
int: n = 5;

% Index sets for clarity
set of int: IDX = 1..n;

% Mapping integers to entities (for reference, not used in model)
% Children: 1=Bernice, 2=Carl, 3=Debby, 4=Sammy, 5=Ted
% Ages: 1=3, 2=5, 3=7, 4=8, 5=10
% Countries: 1=Ethiopia, 2=Kazakhstan, 3=Lithuania, 4=Morocco, 5=Yemen
% Stories: 1=burning bush, 2=captivity, 3=Moses’s youth, 4=Passover, 5=Ten Commandments

% Decision variables: each is a permutation of 1..5 representing the mapping
% The i-th element corresponds to the i-th child in order: Bernice(1), Carl(2), Debby(3), Sammy(4), Ted(5)

array[IDX] of var IDX: ages;      % ages[i] = age index of child i
array[IDX] of var IDX: countries; % countries[i] = country index of child i
array[IDX] of var IDX: stories;   % stories[i] = story index of child i

% All different constraints for each category
constraint all_different(ages);
constraint all_different(countries);
constraint all_different(stories);

% 1. Debby’s family is from Lithuania.
% Debby is child 3, Lithuania is country 3
constraint countries[3] = 3;

% 2. The child who told the story of the Passover is two years older than Bernice.
% Passover story = 4
% Bernice = child 1
% ages are indices 1..5 corresponding to ages 3,5,7,8,10
% We must map age indices to actual ages to check difference of 2 years
% Age values: [3,5,7,8,10]
array[IDX] of int: age_values = [3,5,7,8,10];
constraint
  let {
    var int: passover_age = age_values[ages[index_set(stories,4)]],
    var int: bernice_age = age_values[ages[1]]
  } in
    passover_age = bernice_age + 2;

% 3. The child whose family is from Yemen is younger than the child from the Ethiopian family.
% Yemen = 5, Ethiopia = 1
constraint
  let {
    var int: yemen_age = age_values[ages[index_set(countries,5)]],
    var int: ethiopia_age = age_values[ages[index_set(countries,1)]]
  } in
    yemen_age < ethiopia_age;

% 4. The child from the Moroccan family is three years older than Ted.
% Morocco = 4, Ted = child 5
constraint
  let {
    var int: morocco_age = age_values[ages[index_set(countries,4)]],
    var int: ted_age = age_values[ages[5]]
  } in
    morocco_age = ted_age + 3;

% 5. Sammy is three years older than the child who told the story of Moses’s youth in the house of the Pharaoh.
% Sammy = child 4, Moses’s youth story = 3
constraint
  let {
    var int: sammy_age = age_values[ages[4]],
    var int: moses_youth_age = age_values[ages[index_set(stories,3)]]
  } in
    sammy_age = moses_youth_age + 3;

% Helper function to find index of a value in an array of vars
function var int: index_set(array[int] of var int: arr, int: val) =
  sum(i in IDX)(bool2int(arr[i] == val) * i);

solve satisfy;

output [
  "{",
  join(",", [
    "\"ages\": [" ++ join(",", [show(ages[i]) | i in IDX]) ++ "]",
    "\"children\": [" ++ join(",", [show(i) | i in IDX]) ++ "]",
    "\"countries\": [" ++ join(",", [show(countries[i]) | i in IDX]) ++ "]",
    "\"stories\": [" ++ join(",", [show(stories[i]) | i in IDX]) ++ "]"
  ]),
  "}"
];
```

