include "globals.mzn";

% Decision variables
array[1..4] of var 1..100: nums;

% Distinctness constraint
constraint all_different(nums);

% Naming variables for clarity
var 1..100: a = nums[1];
var 1..100: b = nums[2];
var 1..100: c = nums[3];
var 1..100: d = nums[4];

% Constraint: sum of squares of a and b equals sum of squares of c and d
constraint a*a + b*b = c*c + d*d;

solve satisfy;

output [
    "{",
    "\"a\": " ++ show(a) ++ ",",
    "\"b\": " ++ show(b) ++ ",",
    "\"c\": " ++ show(c) ++ ",",
    "\"d\": " ++ show(d),
    "}"
];
