```minizinc
include "globals.mzn";

% Input data
int: num_people = 8;
array[1..num_people] of array[int] of int: compatible = [
    [2, 3],
    [1, 6],
    [1, 4, 7],
    [2],
    [2],
    [5],
    [8],
    [3]
];

% Decision variables
% transplants[i,j] = 1 if person i donates to person j, 0 otherwise
array[1..num_people, 1..num_people] of var 0..1: transplants;

% Constraints

% 1) Only allow transplants where compatible[i] contains j
constraint
  forall(i in 1..num_people, j in 1..num_people) (
    (transplants[i,j] = 1) -> (j in compatible[i])
  );

% 2) Each person can donate at most one kidney
constraint
  forall(i in 1..num_people) (
    sum(j in 1..num_people)(transplants[i,j]) <= 1
  );

% 3) Each person can receive at most one kidney
constraint
  forall(j in 1..num_people) (
    sum(i in 1..num_people)(transplants[i,j]) <= 1
  );

% 4) Anyone who gives a kidney must receive one
% For each person i, if sum of transplants[i,*] = 1 then sum of transplants[*,i] = 1
constraint
  forall(i in 1..num_people) (
    (sum(j in 1..num_people)(transplants[i,j]) = 1) -> (sum(k in 1..num_people)(transplants[k,i]) = 1)
  );

% Objective: maximize the number of people who receive a kidney
% Number of people who receive a kidney = sum over j of sum over i of transplants[i,j]
% Since each person can receive at most one kidney, sum over i of transplants[i,j] is 0 or 1
var int: total_recipients = sum(j in 1..num_people)(sum(i in 1..num_people)(transplants[i,j]));

solve maximize total_recipients;

output [
    "{",
    "\"transplants\": [",
    join(",\n", [
      "[" ++ join(", ", [show(transplants[i,j]) | j in 1..num_people]) ++ "]"
      | i in 1..num_people
    ]),
    "]",
    "}"
];
```

