int: n = 4;
int: magic_sum = n * (n*n + 1) div 2;

array[1..n, 1..n] of var 1..n*n: square;

% All cells must be different
constraint
    all_different([square[i,j] | i,j in 1..n]);

% Each row sums to magic_sum
constraint
    forall(i in 1..n) (
        sum(j in 1..n)(square[i,j]) == magic_sum
    );

% Each column sums to magic_sum
constraint
    forall(j in 1..n) (
        sum(i in 1..n)(square[i,j]) == magic_sum
    );

% Main diagonal sums to magic_sum
constraint
    sum(i in 1..n)(square[i,i]) == magic_sum;

% Secondary diagonal sums to magic_sum
constraint
    sum(i in 1..n)(square[i,n+1 - i]) == magic_sum;

solve satisfy;

output [
    "{",
    "\"square\": [",
    join(",\n", [
        "[" ++ join(", ", [show(square[i,j]) | j in 1..n]) ++ "]"
        | i in 1..n
    ]),
    "]",
    "}"
