% Number of people
int: total_people = 13;
int: total_males = 4;
int: total_females = total_people - total_males;

% Decision variable: sequence of people entering the room
% 0 represents male, 1 represents female
array[1..total_people] of var 0..1: sequence;

% Constraint: total males and females count
constraint
    sum(i in 1..total_people)(sequence[i]) == total_females /\
    sum(i in 1..total_people)(1 - sequence[i]) == total_males;

% Constraint: ratio of females to males in the room at any time <= 7/3
% For each prefix of the sequence, count females and males and check ratio
constraint
    forall(i in 1..total_people) (
        let {
            var int: females = sum(j in 1..i)(sequence[j]),
            var int: males = i - females
        } in
            % If males == 0, ratio is infinite, so females must be 0 as well (no males no females)
            (males == 0 -> females == 0) /\
            (males > 0 -> females * 3 <= males * 7)
    );

solve satisfy;

output [
    "{",
    "\"sequence\": [" ++ join(", ", [show(sequence[i]) | i in 1..total_people]) ++ "]",
    "}"
];
```

