% Define suspects as indices for convenience
enum SUSPECTS = {artie, bill, crackitt, dodgy, edgy, fingers};

% Decision variables: 1 if guilty, 0 if innocent
array[SUSPECTS] of var 0..1: guilty;

% Number of guilty suspects
var 0..6: num_guilty = sum(s in SUSPECTS)(guilty[s]);

% Number of innocent suspects
var 0..6: num_innocent = 6 - num_guilty;

% At least four are innocent
constraint num_innocent >= 4;

% Innocent tell the truth, guilty lie
% Define a helper function to represent the truthfulness of each statement
% For each suspect, if innocent (guilty=0), statement must be true
% if guilty (guilty=1), statement must be false

% ARTIE: "It wasn't me." -> Artie is not guilty
constraint
  (guilty[artie] = 0 -> guilty[artie] = 0) /\
  (guilty[artie] = 1 -> guilty[artie] = 1); % tautology, but keep for clarity

% Let's define the statements as boolean expressions:

% Artie's statement: "It wasn't me." -> guilty[artie] = 0
var bool: artie_stmt = (guilty[artie] = 0);

% Bill's statement: "Crackitt was in it up to his neck." -> guilty[crackitt] = 1
var bool: bill_stmt = (guilty[crackitt] = 1);

% Crackitt's statement: "No I wasn't." -> guilty[crackitt] = 0
var bool: crackitt_stmt = (guilty[crackitt] = 0);

% Dodgy's statement: "If Crackitt did it, Bill did it with him."
% Logical: if guilty[crackitt] = 1 then guilty[bill] = 1
var bool: dodgy_stmt = (guilty[crackitt] = 0 \/ guilty[bill] = 1);

% Edgy's statement: "Nobody did it alone."
% So no one is the only guilty person
var bool: edgy_stmt = (num_guilty != 1);

% Fingers' statement: "That’s right: it was Artie and Dodgy together."
% So guilty[artie] = 1 and guilty[dodgy] = 1
var bool: fingers_stmt = (guilty[artie] = 1 /\ guilty[dodgy] = 1);

% For each suspect:
% if innocent (guilty=0) then statement is true
% if guilty (guilty=1) then statement is false

constraint (guilty[artie] = 0) <-> artie_stmt;
constraint (guilty[bill] = 0) <-> bill_stmt;
constraint (guilty[crackitt] = 0) <-> crackitt_stmt;
constraint (guilty[dodgy] = 0) <-> dodgy_stmt;
constraint (guilty[edgy] = 0) <-> edgy_stmt;
constraint (guilty[fingers] = 0) <-> fingers_stmt;

solve satisfy;

output [
  "{",
  join(",", [
    "\"artie\": " ++ show(guilty[artie]),
    "\"bill\": " ++ show(guilty[bill]),
    "\"crackitt\": " ++ show(guilty[crackitt]),
    "\"dodgy\": " ++ show(guilty[dodgy]),
    "\"edgy\": " ++ show(guilty[edgy]),
    "\"fingers\": " ++ show(guilty[fingers])
  ]),
  "}"
];
