include "globals.mzn";

% Input data
int: n = 6; % number of 4-hour intervals
array[1..n] of int: demands = [4, 8, 10, 7, 12, 4];

% Decision variables
% x[i] = number of buses starting their 8-hour shift at interval i
array[1..n] of var 0..sum(demands): x;

% Constraints
% Each bus operates 8 successive hours = 2 intervals
% So a bus starting at interval i covers intervals i and i+1 (mod n)
% For each interval j, sum of buses covering j >= demand[j]
% Coverage intervals:
% interval j is covered by buses starting at j and at j-1 (with wrap-around)
constraint
  forall(j in 1..n) (
    let {
      int: prev = if j = 1 then n else j - 1 endif
    } in
      x[prev] + x[j] >= demands[j]
  );

% Objective: minimize total number of buses scheduled
var int: total_buses = sum(i in 1..n)(x[i]);
solve minimize total_buses;

output [
  "{",
  "\"x\": [" ++ join(", ", [show(x[i]) | i in 1..n]) ++ "]",
  "}"
];
```

