include "globals.mzn";

% Input data: jobs_data[job][task] = (machine, duration)
array[int, int] of tuple2(int,int): jobs_data = [
    [(0, 3), (1, 2), (2, 2)],  % Job 0
    [(0, 2), (2, 1), (1, 4)],  % Job 1
    [(1, 4), (2, 3)]           % Job 2
];

int: num_jobs = length(jobs_data);
array[int] of int: num_tasks = [length(jobs_data[j]) | j in 1..num_jobs];

% Extract machines and durations for convenience
array[int, int] of int: machines = array2d(1..num_jobs, 1..max(num_tasks),
    [ if t <= num_tasks[j] then jobs_data[j][t].fst else -1 endif | j,t in 1..num_jobs, 1..max(num_tasks) ]);
array[int, int] of int: durations = array2d(1..num_jobs, 1..max(num_tasks),
    [ if t <= num_tasks[j] then jobs_data[j][t].snd else 0 endif | j,t in 1..num_jobs, 1..max(num_tasks) ]);

% Compute horizon as sum of all durations (upper bound on makespan)
int: horizon = sum(j in 1..num_jobs, t in 1..num_tasks[j]) (durations[j,t]);

% Decision variables: start times of each task
array[int, int] of var 0..horizon: start_times;

% Compute end times for convenience
array[int, int] of var 0..horizon: end_times = 
    array2d(1..num_jobs, 1..max(num_tasks), 
        [start_times[j,t] + durations[j,t] | j,t in 1..num_jobs, 1..max(num_tasks)]);

% Constraint: task order within each job
constraint
    forall(j in 1..num_jobs, t in 1..num_tasks[j]-1) (
        end_times[j,t] <= start_times[j,t+1]
    );

% Constraint: no overlap on the same machine
% For each machine, collect all tasks assigned to it
set of int: Machines = {0,1,2};
constraint
    forall(m in Machines) (
        let {
            array[int] of int: job_task_indices = 
                [ (j-1)*max(num_tasks) + t | j,t in 1..num_jobs, 1..num_tasks[j] where machines[j,t] == m ],
            array[int] of int: jobs_for_m = [j | j,t in 1..num_jobs, 1..num_tasks[j] where machines[j,t] == m],
            array[int] of int: tasks_for_m = [t | j,t in 1..num_jobs, 1..num_tasks[j] where machines[j,t] == m]
        } in
        forall(i,j in 1..length(jobs_for_m) where i < j) (
            let {
                var int: s1 = start_times[jobs_for_m[i], tasks_for_m[i]],
                var int: e1 = end_times[jobs_for_m[i], tasks_for_m[i]],
                var int: s2 = start_times[jobs_for_m[j], tasks_for_m[j]],
                var int: e2 = end_times[jobs_for_m[j], tasks_for_m[j]]
            } in
            (e1 <= s2) \/ (e2 <= s1)
        )
    );

% Objective: minimize makespan = max of all end times
var 0..horizon: makespan = max([end_times[j,t] | j in 1..num_jobs, t in 1..num_tasks[j]]);

solve minimize makespan;

output [
    "{",
    "\"makespan\": " ++ show(makespan),
    "}"
];
