include "globals.mzn";

% Input data
int: rows = 8;
int: cols = 8;
int: X = -1;

array[1..rows, 1..cols] of int: game_data = [
    | 2, 3, X, 2, 2, X, 2, 1,
      X, X, 4, X, X, 4, X, 2,
      X, X, X, X, X, X, 4, X,
      X, 5, X, 6, X, X, X, 2,
      2, X, X, X, 5, 5, X, 2,
      1, 3, 4, X, X, X, 4, X,
      0, 1, X, 4, X, X, X, 3,
      0, 1, 2, X, 2, 3, X, 2
];

% Decision variables
% mines[r,c] = 1 if cell (r,c) is a mine, 0 otherwise
array[1..rows, 1..cols] of var 0..1: mines;

% Constraints

% 1) Cells that are opened (game_data[r,c] != X) cannot be mines
constraint
  forall(r in 1..rows, c in 1..cols) (
    if game_data[r,c] != X then
      mines[r,c] = 0
    else
      true
    endif
  );

% 2) For each opened cell, the number must equal the sum of mines in adjacent cells
% Define neighbors offsets
set of int: delta = -1..1;

constraint
  forall(r in 1..rows, c in 1..cols where game_data[r,c] != X) (
    let {
      array[int] of int: nr = [r + dr | dr in delta where 1 <= r+dr <= rows],
      array[int] of int: nc = [c + dc | dc in delta where 1 <= c+dc <= cols]
    } in
      game_data[r,c] = sum(rr in nr, cc in nc) (
        if rr != r \/ cc != c then mines[rr,cc] else 0 endif
      )
  );

solve satisfy;

output [
  "{",
  join(",", [
    "\"" ++ "mines" ++ "\": [" ++
      join(",",
        [ "[" ++ join(",", [show(mines[r,c]) | c in 1..cols]) ++ "]" | r in 1..rows ]
      )
    ++ "]"
  ]),
  "}"
];
