include "globals.mzn";

% Input data
int: max_rooms = 5;
int: num_requests = 4;

% Dates as strings
array[1..num_requests] of string: start_data = ["2024-05-01", "2024-05-02", "2024-05-03", "2024-05-04"];
array[1..num_requests] of string: end_data = ["2024-05-05", "2024-05-06", "2024-05-07", "2024-05-08"];

% Preassigned rooms (-1 means no pre-assignment)
array[1..num_requests] of int: preassigned_room_data = [3, -1, -1, -1];

% Convert date strings to integer days for easier comparison
% We parse the date strings "YYYY-MM-DD" into an integer representing days since a fixed date.
% For simplicity, we convert dates to days since 2024-01-01.

function int: date_to_day(string: date) =
    let {
        int: year = fix(substr(date,1,4)),
        int: month = fix(substr(date,6,2)),
        int: day = fix(substr(date,9,2))
    } in
    % Days since 2024-01-01 (ignoring leap years for simplicity, but 2024 is a leap year)
    % We handle months with days count and leap year 2024
    let {
        array[1..12] of int: days_in_month = [31,29,31,30,31,30,31,31,30,31,30,31],
        int: days_before_month = sum(i in 1..month-1)(days_in_month[i])
    } in
    (year - 2024)*366 + days_before_month + day;

array[1..num_requests] of int: start_days = [date_to_day(start_data[i]) | i in 1..num_requests];
array[1..num_requests] of int: end_days = [date_to_day(end_data[i]) | i in 1..num_requests];

% Decision variables
array[1..num_requests] of var 1..max_rooms: room_assignments;

% Constraints

% Enforce preassigned rooms
constraint
    forall(i in 1..num_requests) (
        if preassigned_room_data[i] != -1 then
            room_assignments[i] = preassigned_room_data[i]
        else
            true
        endif
    );

% No overlapping requests in the same room
% Two requests i and j overlap if their intervals intersect:
% i and j overlap if not (end_i < start_j or end_j < start_i)
constraint
    forall(i,j in 1..num_requests where i < j) (
        if not (end_days[i] < start_days[j] \/ end_days[j] < start_days[i]) then
            room_assignments[i] != room_assignments[j]
        else
            true
        endif
    );

solve satisfy;

output [
    "{",
    "\"room_assignments\": [" ++ join(", ", [show(room_assignments[i]) | i in 1..num_requests]) ++ "]",
    "}"
];
