array[1..n] of int: y = [149, 129, 133, 141, 163, 157, 169, 169, 148, 164, 172, 159];

% Calculate Euclidean distances between cities, rounded to nearest integer
array[1..n, 1..n] of int: dist = 
  array2d(1..n, 1..n, 
    [ round(sqrt((x[i]-x[j])*(x[i]-x[j]) + (y[i]-y[j])*(y[i]-y[j]))) | i,j in 1..n ]);

% Decision variables:
% succ[i] = city visited immediately after city i in the tour
array[1..n] of var 1..n: succ;

% To eliminate subtours, use MTZ formulation with order variables
array[1..n] of var 1..n: order;

% Constraints:

% 1) Each city has exactly one successor (implied by succ domain and all_different)
constraint
  all_different(succ);

% 2) The order variables define the position of each city in the tour
% Fix order of city 1 to 1 to break symmetry
constraint order[1] = 1;

% 3) MTZ subtour elimination constraints
% For all i != 1 and j != 1:
% order[i] + 1 <= order[succ[i]] or order[succ[i]] = 1 (handled by order domain)
constraint
  forall(i in 1..n where i != 1) (
    order[i] >= 2 /\ order[i] <= n
  );

constraint
  forall(i in 1..n where i != 1) (
    order[succ[i]] = order[i] + 1 \/ (order[i] = n /\ order[succ[i]] = 1)
  );

% Objective: minimize total travel distance
var int: travel_distance = sum(i in 1..n)(dist[i, succ[i]]);

solve minimize travel_distance;

output [
  "{",
  "\"travel_distance\": " ++ show(travel_distance),
  "}"
];
