% Include necessary library for global constraints
include "globals.mzn";

% Input data
int: n = 3;
array[1..n] of string: names = ["Agatha herself", "the butler", "Charles"];

% Indexes for clarity
int: Agatha = 1;
int: Butler = 2;
int: Charles = 3;

% Decision variables
% killer: index of the killer (1..3)
var 1..n: killer;

% hates[i,j] = true if person i hates person j
array[1..n, 1..n] of var bool: hates;

% richer[i,j] = true if person i is richer than person j
array[1..n, 1..n] of var bool: richer;

% Constraints

constraint
  % No one hates themselves
  forall(i in 1..n) (
    hates[i,i] = false
  );

constraint
  % Agatha hates everybody except the butler
  forall(j in 1..n) (
    hates[Agatha,j] = (j != Butler)
  );

constraint
  % Charles hates no one that Agatha hates
  forall(j in 1..n) (
    hates[Charles,j] -> hates[Agatha,j]
  );

constraint
  % The butler hates everyone not richer than Agatha
  forall(j in 1..n) (
    (not richer[j,Agatha]) -> hates[Butler,j]
  );

constraint
  % The butler hates everyone whom Agatha hates
  forall(j in 1..n) (
    hates[Agatha,j] -> hates[Butler,j]
  );

constraint
  % No one hates everyone
  forall(i in 1..n) (
    exists(j in 1..n) (not hates[i,j])
  );

constraint
  % A killer always hates their victim (Agatha)
  hates[killer,Agatha] = true;

constraint
  % A killer is no richer than their victim (Agatha)
  richer[killer,Agatha] = false;

% Additional constraints for richer relation:
% We assume richer relation is irreflexive and antisymmetric
constraint
  forall(i in 1..n) (
    richer[i,i] = false
  );

constraint
  forall(i,j in 1..n where i != j) (
    richer[i,j] -> not richer[j,i]
  );

% We do not assume total order on richness, so no further constraints

solve satisfy;

output [
  "{",
  "\"killer\": " ++ show(killer),
  "}"
];
```

