int: stage = 8;  % Number of stages

% Positions: 0 = starting shore, 1 = destination shore
array[1..stage] of var 0..1: wolf_pos;
array[1..stage] of var 0..1: goat_pos;
array[1..stage] of var 0..1: cabbage_pos;
array[1..stage] of var 0..1: boat_pos;

% Initial positions: all on starting shore
constraint wolf_pos[1] = 0;
constraint goat_pos[1] = 0;
constraint cabbage_pos[1] = 0;
constraint boat_pos[1] = 0;

% Final positions: all on destination shore
constraint wolf_pos[stage] = 1;
constraint goat_pos[stage] = 1;
constraint cabbage_pos[stage] = 1;
constraint boat_pos[stage] = 1;

% At each stage, the boat moves with farmer and possibly one item
% Between consecutive stages, the boat and possibly one item move to the other shore

% Helper function: number of items moved (0 or 1)
function var int: moved_items(int: t) =
  (wolf_pos[t] != wolf_pos[t+1] ? 1 : 0) +
  (goat_pos[t] != goat_pos[t+1] ? 1 : 0) +
  (cabbage_pos[t] != cabbage_pos[t+1] ? 1 : 0);

% Constraints for each transition between stages
constraint
  forall(t in 1..stage-1) (
    % Boat must move to the other shore
    boat_pos[t] != boat_pos[t+1] /\
    % Items can only move if boat moves with them
    % The boat moves with farmer and at most one item
    moved_items(t) <= 1 /\
    % Items that move must move with the boat
    (wolf_pos[t] != wolf_pos[t+1] -> wolf_pos[t] = boat_pos[t]) /\
    (goat_pos[t] != goat_pos[t+1] -> goat_pos[t] = boat_pos[t]) /\
    (cabbage_pos[t] != cabbage_pos[t+1] -> cabbage_pos[t] = boat_pos[t]) /\
    % Items that do not move stay on their shore
    (wolf_pos[t] = wolf_pos[t+1] \/ wolf_pos[t] = boat_pos[t]) /\
    (goat_pos[t] = goat_pos[t+1] \/ goat_pos[t] = boat_pos[t]) /\
    (cabbage_pos[t] = cabbage_pos[t+1] \/ cabbage_pos[t] = boat_pos[t])
  );

% Safety constraints at each stage:
% If farmer (boat) is not on the same shore as goat, then wolf and goat cannot be alone together
% and goat and cabbage cannot be alone together
constraint
  forall(t in 1..stage) (
    let {
      var int: shore = 1 - boat_pos[t]  % shore without farmer
    } in
    not (
      goat_pos[t] = shore /\
      (
        (wolf_pos[t] = shore) \/
        (cabbage_pos[t] = shore)
      )
    )
  );

solve satisfy;

output [
  "{",
  join(",", [
    "\"" ++ "wolf_pos" ++ "\": [" ++ join(",", [show(wolf_pos[t]) | t in 1..stage]) ++ "]",
    "\"" ++ "goat_pos" ++ "\": [" ++ join(",", [show(goat_pos[t]) | t in 1..stage]) ++ "]",
