include "globals.mzn";

% Input data
int: n_weeks = 4;      % Number of weeks
int: n_groups = 3;     % Number of groups per week
int: group_size = 3;   % Number of golfers per group
int: n_golfers = n_groups * group_size; % Total number of golfers

% Decision variable:
% assign[w,g,p] = golfer assigned to position p in group g in week w
array[1..n_weeks, 1..n_groups, 1..group_size] of var 1..n_golfers: assign;

% CONSTRAINTS

% 1) Each golfer plays exactly once per week
% For each week, the assign variables form a permutation of all golfers
constraint
  forall(w in 1..n_weeks) (
    alldifferent([assign[w,g,p] | g in 1..n_groups, p in 1..group_size])
  );

% 2) No golfer plays in the same group as any other golfer more than once
% For each pair of golfers, they can be together in at most one group over all weeks

% We will enforce that for any pair of distinct golfers (g1,g2),
% the number of times they appear together in the same group (same week and group) is <= 1

% To do this, we consider all pairs of golfers and count how many times they appear together

% Precompute all pairs of golfers
set of int: Golfers = 1..n_golfers;
array[1..(n_golfers*(n_golfers-1)) div 2] of tuple(var int,var int): golfer_pairs =
  [ (i,j) | i,j in Golfers where i < j ];

% For each pair, count the number of times they appear together in the same group
constraint
  forall(pair in golfer_pairs) (
    let {
      var int: count_together = sum(w in 1..n_weeks, g in 1..n_groups) (
        % Check if both golfers in pair appear in assign[w,g,*]
        bool2int(
          exists(p1 in 1..group_size)(assign[w,g,p1] = pair[1]) /\
          exists(p2 in 1..group_size)(assign[w,g,p2] = pair[2])
        )
      )
    } in
      count_together <= 1
  );

solve satisfy;

output [
  "{",
  "\"assign\": [",
  join(",\n", [
    "[ " ++
    join(", ", [
      "[ " ++ join(", ", [show(assign[w,g,p]) | p in 1..group_size]) ++ " ]"
      | g in 1..n_groups
    ]) ++ " ]"
    | w in 1..n_weeks
  ]),
  "]",
  "}"
];
```

