```minizinc
include "globals.mzn";

% Input data
int: n_boats = 5;               % Number of boats
int: n_periods = 4;             % Number of periods
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12]; % Capacities of boats
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];  % Crew sizes of boats

% Decision variables

% is_host[b] = 1 if boat b is a host, 0 otherwise
array[1..n_boats] of var 0..1: is_host;

% visits[p,b] = the host boat visited by boat b at period p
% For host boats, visits[p,b] = b (they stay on their own boat)
array[1..n_periods, 1..n_boats] of var 1..n_boats: visits;

% Constraints

% 1) Hosts visit themselves at all periods
constraint
  forall(b in 1..n_boats, p in 1..n_periods) (
    is_host[b] = 1 -> visits[p,b] = b
  );

% 2) Guests visit only host boats
constraint
  forall(b in 1..n_boats, p in 1..n_periods) (
    is_host[b] = 0 -> is_host[visits[p,b]] = 1
  );

% 3) A guest boat cannot visit the same host more than once
constraint
  forall(b in 1..n_boats where is_host[b] = 0) (
    forall(p1, p2 in 1..n_periods where p1 < p2) (
      visits[p1,b] != visits[p2,b]
    )
  );

% 4) A guest boat cannot visit itself (only hosts can stay on their own boat)
constraint
  forall(b in 1..n_boats where is_host[b] = 0, p in 1..n_periods) (
    visits[p,b] != b
  );

% 5) Capacity constraints: For each host boat h and period p,
% sum of crew sizes of host h plus all guests visiting h at p <= capacity[h]
constraint
  forall(h in 1..n_boats, p in 1..n_periods) (
    let {
      set of int: guests_visiting = {b | b in 1..n_boats where visits[p,b] = h}
    } in
      sum(b in guests_visiting)(crew_size[b]) <= capacity[h]
  );

% 6) Guests cannot meet more than once:
% For any two distinct guest boats g1 and g2, they cannot be on the same host boat at the same period more than once
constraint
  forall(g1, g2 in 1..n_boats where g1 < g2 /\ is_host[g1] = 0 /\ is_host[g2] = 0) (
    sum(p in 1..n_periods)(bool2int(visits[p,g1] = visits[p,g2])) <= 1
  );

% 7) Hosts do not meet guests on other hosts (guests only visit hosts)
% This is implicitly ensured by previous constraints.

% Objective: minimize number of hosts
var int: num_hosts = sum(b in 1..n_boats)(is_host[b]);

solve minimize num_hosts;

% Output the visit schedule and host designations in JSON format
output [
  "{",
  "\"visits\": [",
  join(",\n", [
    "[" ++ join(", ", [show(visits[p,b]) | b in 1..n_boats]) ++ "]"
    | p in 1..n_periods
  ]),
  "],",
  "\"is_host\": [" ++ join(", ", [show(is_host[b]) | b in 1..n_boats]) ++ "]",
  "}"
];
