% Input data
int: n_teams = 8;
int: n_weeks = n_teams - 1;
int: n_periods = n_teams div 2;

% Sets
set of int: TEAMS = 0..n_teams-1;
set of int: WEEKS = 1..n_weeks;
set of int: PERIODS = 1..n_periods;

% Decision variables:
% home[w,p] = team playing at home in week w, period p
array[WEEKS, PERIODS] of var TEAMS: home;
% away[w,p] = team playing away in week w, period p
array[WEEKS, PERIODS] of var TEAMS: away;

% Constraints

% 1) Every team plays once a week (either home or away)
constraint
  forall(w in WEEKS) (
    % Collect all teams playing in week w
    let {
      array[1..n_teams] of var TEAMS: teams_in_week = 
        [home[w,p] | p in PERIODS] ++ [away[w,p] | p in PERIODS]
    } in
    % All teams in week w are distinct
    all_different(teams_in_week)
  );

% 2) Every team plays every other team exactly once (round robin)
% For each pair of distinct teams (t1,t2), they meet exactly once, either t1 home and t2 away or vice versa
constraint
  forall(t1, t2 in TEAMS where t1 < t2) (
    sum(w in WEEKS, p in PERIODS) (
      bool2int(home[w,p] == t1 /\ away[w,p] == t2) +
      bool2int(home[w,p] == t2 /\ away[w,p] == t1)
    ) == 1
  );

% 3) Every team plays at most twice in the same period over the tournament
% For each team and period, count how many times the team plays in that period (home or away)
constraint
  forall(t in TEAMS, p in PERIODS) (
    sum(w in WEEKS) (
      bool2int(home[w,p] == t) + bool2int(away[w,p] == t)
    ) <= 2
  );

% Additional constraints to avoid a team playing against itself
constraint
  forall(w in WEEKS, p in PERIODS) (
    home[w,p] != away[w,p]
  );

% Solve satisfy
solve satisfy;

% Output the home and away schedules as lists of lists of integers
output [
  "{",
  "\"home\": [" ++
    join(",",
      [ "[" ++ join(",", [show(home[w,p]) | p in PERIODS]) ++ "]" | w in WEEKS ]
    )
  ++ "],",
  "\"away\": [" ++
    join(",",
      [ "[" ++ join(",", [show(away[w,p]) | p in PERIODS]) ++ "]" | w in WEEKS ]
    )
  ++ "]",
  "}"
];
