include "globals.mzn";

% Problem parameters
int: n = 8; % Number of words to find
int: len = 8; % Length of each word
set of int: POS = 1..len;

% Alphabet encoding: A=1, C=2, G=3, T=4
set of int: ALPH = 1..4;

% Complement mapping: A<->T, C<->G
array[ALPH] of int: complement = [4,3,2,1];

% Decision variables: words[w,p] is the symbol at position p in word w
array[1..n, POS] of var ALPH: words;

% Constraint 1: Each word has exactly 4 symbols from {C,G} i.e. symbols 2 or 3
constraint
  forall(w in 1..n) (
    sum(p in POS)(bool2int(words[w,p] == 2 \/ words[w,p] == 3)) == 4
  );

% Function to compute Hamming distance between two words
function var int: hamming_dist(array[int] of var int: x, array[int] of var int: y) =
  sum(p in POS)(bool2int(x[p] != y[p]));

% Function to compute reverse of a word
function array[int] of var int: reverse_word(array[int] of var int: x) =
  [x[len - p + 1] | p in POS];

% Function to compute complement of a word
function array[int] of var int: complement_word(array[int] of var int: x) =
  [complement[x[p]] | p in POS];

% Constraint 2: Each pair of distinct words differ in at least 4 positions
constraint
  forall(i,j in 1..n where i < j) (
    hamming_dist([words[i,p] | p in POS], [words[j,p] | p in POS]) >= 4
  );

% Constraint 3: For each pair (x,y), hamming distance between reverse(x) and complement(y) >= 4
constraint
  forall(i,j in 1..n) (
    hamming_dist(reverse_word([words[i,p] | p in POS]), complement_word([words[j,p] | p in POS])) >= 4
  );

solve satisfy;

output [
  "{",
  "\"words\": [",
  join(",\n", [
    "[" ++ join(",", [show(words[w,p]) | p in POS]) ++ "]"
    | w in 1..n
  ]),
  "]",
  "}"
];
