include "globals.mzn";

% Input data
int: n = 9;

% Number of triples in the Steiner Triple System
int: num_triples = n * (n - 1) div 6;

% The set of elements
set of int: Elements = 1..n;

% Decision variables:
% triples[t, p] = element at position p (1..3) in triple t (1..num_triples)
array[1..num_triples, 1..3] of var Elements: triples;

% Constraints:

% 1) Each triple consists of distinct elements
constraint
  forall(t in 1..num_triples) (
    alldifferent([triples[t, p] | p in 1..3])
  );

% 2) Sort each triple to avoid permutations of the same triple
% Enforce triples[t,1] < triples[t,2] < triples[t,3]
constraint
  forall(t in 1..num_triples) (
    triples[t,1] < triples[t,2] /\ triples[t,2] < triples[t,3]
  );

% 3) Any pair of elements appears in exactly one triple
% For all pairs (i,j) with i<j, the number of triples containing both i and j is exactly 1
% We model this by counting for each pair how many triples contain it

% Generate all pairs i<j
set of tuple(int,int): Pairs = { (i,j) | i,j in Elements where i < j };

% For each pair, count how many triples contain both elements
constraint
  forall((i,j) in Pairs) (
    sum(t in 1..num_triples) (
      bool2int(
        (triples[t,1] == i \/ triples[t,2] == i \/ triples[t,3] == i) /\
        (triples[t,1] == j \/ triples[t,2] == j \/ triples[t,3] == j)
      )
    ) == 1
  );

solve satisfy;

output [
  "{",
  "\"triples\": [",
  join(",\n", [
    "[" ++ show(triples[t,1]) ++ "," ++ show(triples[t,2]) ++ "," ++ show(triples[t,3]) ++ "]"
    | t in 1..num_triples
  ]),
  "]",
  "}"
];
