include "globals.mzn";

% Input data
int: n = 12;

% Check precondition: n must be >= 8 and multiple of 4 for a solution to exist
constraint n >= 8 /\ n mod 4 = 0;

% Sets A and B each have n/2 elements
int: half = n div 2;

% Decision variables: arrays of booleans indicating membership in set A
array[1..n] of var bool: inA;

% Cardinality constraint: exactly half elements in A
constraint sum(i in 1..n)(bool2int(inA[i])) = half;

% Sum of elements in A equals sum of elements in B
% sum of elements in A = sum of elements in B = total_sum / 2
int: total_sum = n*(n+1) div 2;
constraint sum(i in 1..n)(bool2int(inA[i]) * i) = total_sum div 2;

% Sum of squares of elements in A equals sum of squares of elements in B
int: total_sum_sq = n*(n+1)*(2*n+1) div 6;
constraint sum(i in 1..n)(bool2int(inA[i]) * i * i) = total_sum_sq div 2;

% Define sets A and B from inA
array[1..half] of var 1..n: A;
array[1..half] of var 1..n: B;

% Extract elements in A and B
% We use a global constraint to ensure A contains exactly the elements where inA[i] = true
% and B contains the rest

% Auxiliary arrays to hold indices of elements in A and B
var int: countA = half;
var int: countB = half;

% We enforce that A and B are disjoint and cover all elements 1..n
% We use the following approach:
% - A contains elements i where inA[i] = true
% - B contains elements i where inA[i] = false

% We collect elements in A and B by filtering
% We use the global constraint 'global_cardinality' to ensure uniqueness and coverage

% To extract A and B arrays, we use the following approach:
% We create arrays of indices for A and B positions
array[1..n] of var 0..1: inA_int = [bool2int(inA[i]) | i in 1..n];

% We define arrays A and B as the elements where inA[i] = 1 and 0 respectively
% We use the global constraint 'count' to ensure correct number of elements

% We use the 'array_var_int' trick to extract elements:
% We create arrays of all elements 1..n
array[1..n] of int: elements = [i | i in 1..n];

% We define arrays of var int for A and B with fixed size half
% We use the 'array_var_int' and 'element' constraints to link them

% We create arrays of indices for A and B positions
array[1..half] of var 1..n: posA;
array[1..half] of var 1..n: posB;

% posA are positions in elements array where inA[i] = 1
% posB are positions in elements array where inA[i] = 0

% We enforce that posA and posB are all different and cover all elements
constraint alldifferent(posA);
constraint alldifferent(posB);
constraint forall(i in 1..half)(inA[posA[i]] = true);
constraint forall(i in 1..half)(inA[posB[i]] = false);

% A and B are elements at positions posA and posB
constraint forall(i in 1..half)(A[i] = elements[posA[i]]);
constraint forall(i in 1..half)(B[i] = elements[posB[i]]);

% Solve satisfy
solve satisfy;

output [
    "{",
    "\"A\": [" ++ join(", ", [show(A[i]) | i in 1..half]) ++ "],",
    "\"B\": [" ++ join(", ", [show(B[i]) | i in 1..half]) ++ "]",
    "}"
];
