constraint
  forall(i in 1..N) (
    matrix[i,i] = 0
  );

% 2) Symmetric adjacency matrix (undirected graph)
constraint
  forall(i,j in 1..N where i < j) (
    matrix[i,j] = matrix[j,i]
  );

% 3) Degree calculation
constraint
  forall(i in 1..N) (
    degree[i] = sum(j in 1..N)(matrix[i,j])
  );

% 4) Degree sequence is non-increasing
constraint
  forall(i in 1..N-1) (
    degree[i] >= degree[i+1]
  );

% 5) Each degree > 0 and multiple of 3 (already ensured by domain Degrees)

% 6) Sum of degrees is divisible by 12
constraint
  sum(i in 1..N)(degree[i]) mod 12 = 0;

