% 2cc Hadamard Matrix Legendre Pairs CSP for odd l
% Variables: a_1..a_l, b_1..b_l in {-1,1}
% Constraints:
%   For s=1..m: PAF(A,s) + PAF(B,s) = -2
%   Sum of a_i = 1
%   Sum of b_i = 1

include "globals.mzn";

int: l = 9; % odd positive integer
int: m = (l - 1) div 2;

% Domain for variables: -1 or 1
set of int: Dom = {-1,1};

% Decision variables
array[1..l] of var Dom: a;
array[1..l] of var Dom: b;

% Function to compute periodic autocorrelation function PAF for sequence seq at shift s
function var int: PAF(array[int] of var int: seq, int: s) =
    sum(i in 1..l) (seq[i] * seq[if i + s <= l then i + s else i + s - l endif]);

% Constraints
constraint
    forall(s in 1..m) (
        PAF(a,s) + PAF(b,s) = -2
    );

constraint sum(i in 1..l)(a[i]) = 1;
constraint sum(i in 1..l)(b[i]) = 1;

solve satisfy;

output [
    "{",
    "\"a\": [" ++ join(", ", [show(a[i]) | i in 1..l]) ++ "],",
    "\"b\": [" ++ join(", ", [show(b[i]) | i in 1..l]) ++ "]",
    "}"
];
