% We have two ages: m (my age) and h (my husband's age)
% We apply the four operations +2, /8, -3, *7 in some order to m to get h
% and apply the same four operations in a different order to h to get m.

% The operations are:
% +2 (add 2)
% /8 (divide by 8)
% -3 (subtract 3)
% *7 (multiply by 7)

% We want to find integers m and h such that:
% There exists a permutation p1 of the operations so that applying p1 to m yields h
% There exists a different permutation p2 of the operations so that applying p2 to h yields m

include "globals.mzn";

% Define the four operations as functions on floats
% We will work with floats internally to handle division, but ages must be integers
% We will check that intermediate results are integers (or at least final results are integers)

% Represent operations as integers 1..4:
% 1: +2
% 2: /8
% 3: -3
% 4: *7

% We will try all permutations of these operations applied in order

% To handle intermediate results, we use floats, but ages are integers

% We will limit ages to a reasonable range, say 1..100

int: MAX_AGE = 100;

% Variables for ages
var 1..MAX_AGE: m;
var 1..MAX_AGE: h;

% The four operations encoded as functions
function float: op(float x, int o) =
    if o == 1 then x + 2
    elseif o == 2 then x / 8.0
    elseif o == 3 then x - 3
    else x * 7 endif;

% We want to find permutations p1 and p2 of [1,2,3,4]
array[1..4] of int: ops = [1,2,3,4];

% Decision variables for permutations
array[1..4] of var 1..4: p1;
array[1..4] of var 1..4: p2;

% p1 and p2 are permutations of ops
constraint alldifferent(p1);
constraint alldifferent(p2);

% p1 and p2 are different permutations
constraint exists(i in 1..4)(p1[i] != p2[i]);

% Function to apply a sequence of operations to a starting value
function float: apply_ops(float start, array[int] of int ops_seq) =
    let {
        array[0..4] of float: vals = 
            array1d(0..4, [start] ++ [0.0,0.0,0.0,0.0])
    } in
    let {
        array[1..4] of float: res = 
            [op(vals[i-1], ops_seq[i]) | i in 1..4]
    } in
    res[4];

% Because we want to check intermediate results are integers (or at least final results),
% we will model the intermediate results as variables and constrain them to be integers.

% Intermediate results for p1 applied to m
array[0..4] of var float: vals1;
constraint vals1[0] = float(m);
constraint forall(i in 1..4) (
    vals1[i] = op(vals1[i-1], p1[i])
);

% Intermediate results for p2 applied to h
array[0..4] of var float: vals2;
constraint vals2[0] = float(h);
constraint forall(i in 1..4) (
    vals2[i] = op(vals2[i-1], p2[i])
);

% The final results must be integers and equal to the other age
constraint vals1[4] = float(h);
constraint vals2[4] = float(m);

% Also, intermediate results must be integers (to avoid fractional ages in between)
constraint forall(i in 1..4) (
    vals1[i] = float(round(vals1[i]))
    /\ vals2[i] = float(round(vals2[i]))
);

% Solve satisfy
solve satisfy;

output [
    "{",
    "\"m\": " ++ show(m) ++ ",",
    "\"h\": " ++ show(h),
    "}"
];
```

