% Include necessary library for global constraints
include "globals.mzn";

% Decision variables: quantities of each fruit
var 0..100: bananas;
var 0..100: oranges;
var 0..100: mangoes;
var 0..100: apples;

% Constraints

% Total fruits must be 100
constraint bananas + oranges + mangoes + apples == 100;

% Total cost must be 100 dollars
% Cost per fruit: bananas=3/5, oranges=5/7, mangoes=7/9, apples=9/3
% To avoid fractions, multiply cost equation by 315 (LCM of denominators 5,7,9,3)
% 3/5 * bananas = (3*63)/315 * bananas = 189/315 * bananas
% 5/7 * oranges = (5*45)/315 * oranges = 225/315 * oranges
% 7/9 * mangoes = (7*35)/315 * mangoes = 245/315 * mangoes
% 9/3 * apples = (9*105)/315 * apples = 315/315 * apples
% So: 189*bananas + 225*oranges + 245*mangoes + 315*apples = 31500
constraint 189 * bananas + 225 * oranges + 245 * mangoes + 315 * apples == 31500;

% All types of fruits need to be purchased
constraint bananas >= 1;
constraint oranges >= 1;
constraint mangoes >= 1;
constraint apples >= 1;

% Minimize bananas and apples (since user dislikes them)
% We minimize the sum of bananas and apples
solve minimize bananas + apples;

output [
    "{",
    "\"bananas\": " ++ show(bananas) ++ ",",
    "\"oranges\": " ++ show(oranges) ++ ",",
    "\"mangoes\": " ++ show(mangoes) ++ ",",
    "\"apples\": " ++ show(apples),
    "}"
];
