% Include necessary library for global constraints
include "globals.mzn";

% Guests indexed as:
% 0: Andrew
% 1: Betty
% 2: Cara
% 3: Dave
% 4: Erica
% 5: Frank

int: n = 6;

% Allowed neighbors for each guest (as sets)
% Andrew(0): only next to Dave(3) and Frank(5)
% Betty(1): only next to Cara(2) and Erica(4)
% Cara(2): only next to Betty(1) and Frank(5)
% Dave(3): only next to Andrew(0) and Erica(4)
% Erica(4): only next to Betty(1) and Dave(3)
% Frank(5): only next to Andrew(0) and Cara(2)

set of int: Guests = 0..n-1;

array[Guests] of set of int: allowed_neighbors = [
    {3,5},    % Andrew
    {2,4},    % Betty
    {1,5},    % Cara
    {0,4},    % Dave
    {1,3},    % Erica
    {0,2}     % Frank
];

% Decision variable: seating order, x[i] is guest at seat i
array[0..n-1] of var Guests: x;

% All guests must be seated exactly once
constraint
    all_different(x);

% Since the table is circular, neighbors are (i, (i+1) mod n)
% We count conflicts: if two neighbors are not allowed neighbors of each other, conflict = 1

array[0..n-1] of var 0..1: conflict;

constraint
    forall(i in 0..n-1) (
        let {
            var int: g1 = x[i],
            var int: g2 = x[(i+1) mod n]
        } in
        % conflict if g2 not in allowed_neighbors[g1]
        conflict[i] = bool2int(not (g2 in allowed_neighbors[g1]))
    );

% Objective: minimize total conflicts
var 0..n: total_conflicts = sum(i in 0..n-1)(conflict[i]);

solve minimize total_conflicts;

output [
    "{",
    "\"x\": [" ++ join(", ", [show(x[i]) | i in 0..n-1]) ++ "]",
    "}"
];
```

