% Number of dice and faces per die
int: num_dice = 5;
int: faces = 6;

% The beats relationships as pairs (winner, loser)
array[1..10, 1..2] of int: beats = [
    | 1, 3  % Rock crushes Scissors
    | 1, 4  % Rock crushes Lizard
    | 2, 1  % Paper covers Rock
    | 2, 5  % Paper disproves Spock
    | 3, 2  % Scissors cuts Paper
    | 3, 4  % Scissors decapitate Lizard
    | 4, 2  % Lizard eats Paper
    | 4, 5  % Lizard poisons Spock
    | 5, 1  % Spock vaporizes Rock
    | 5, 3  % Spock smashes Scissors
];

% Decision variables: dice[i,j] is the face value of die i on face j
array[1..num_dice, 1..faces] of var 1..30: dice;

% Constraint: all faces on a die are distinct
constraint
  forall(i in 1..num_dice) (
    alldifferent([dice[i,f] | f in 1..faces])
  );

% Constraint: all faces across all dice are distinct (optional for uniqueness)
% Commented out because not required by problem, but can be enabled if desired
% constraint alldifferent([dice[i,f] | i in 1..num_dice, f in 1..faces]);

% For each beats relationship, the winning die should beat the losing die more than half the time
% i.e. number of pairs (face_winner, face_loser) with face_winner > face_loser > faces*faces/2
constraint
  forall(b in 1..10) (
    let {
      int: winner = beats[b,1],
      int: loser = beats[b,2]
    } in
      sum([bool2int(dice[winner,f1] > dice[loser,f2]) | f1,f2 in 1..faces]) > faces*faces div 2
  );

% To reduce symmetry, order dice by their minimal face value
constraint
  forall(i in 1..num_dice-1) (
    min([dice[i,f] | f in 1..faces]) < min([dice[i+1,f] | f in 1..faces])
  );

solve satisfy;

output [
  "{",
  "\"dice\": [",
  join(",\n", [
    "[" ++ join(", ", [show(dice[i,f]) | f in 1..faces]) ++ "]"
    | i in 1..num_dice
  ]),
  "]",
  "}"
];
