include "globals.mzn";

% The total weight of the four pieces
int: total_weight = 40;

% Decision variables: weights of the four pieces
array[1..4] of var 1..total_weight: weights;

% Sort weights to avoid symmetric solutions
constraint forall(i in 1..3) (weights[i] <= weights[i+1]);

% The sum of the four pieces must be 40
constraint sum(i in 1..4)(weights[i]) == total_weight;

% We need to be able to weigh every integral weight from 1 to 40
% using the four pieces on a balance scale.
% Each piece can be on the left pan (-1), right pan (+1), or not used (0).
% For each weight w in 1..40, there must exist a configuration of placements
% of the four pieces such that sum of (placement[i] * weights[i]) = w.

% Define placements: for each weight w, an array of 4 placements in {-1,0,1}
array[1..total_weight, 1..4] of var -1..1: placements;

% For each weight w, the sum of placements * weights must be w
constraint forall(w in 1..total_weight) (
    sum(i in 1..4)(placements[w,i] * weights[i]) == w
);

% Solve to find any solution satisfying the constraints
solve satisfy;

% Output the weights array as JSON
output [
    "{",
    "\"weights\": [" ++ join(", ", [show(weights[i]) | i in 1..4]) ++ "]",
    "}"
];
