include "globals.mzn";

% Input data
int: n = 5;

% The grid is n x n
% We want to fill the grid with numbers from 1 to n*n
% x[r,c] = the number placed at row r, column c
array[1..n, 1..n] of var 1..n*n: x;

% We also want to know the position of each number in the sequence
% pos_row[v] and pos_col[v] give the row and column of number v
array[1..n*n] of var 1..n: pos_row;
array[1..n*n] of var 1..n: pos_col;

% Constraint: all numbers from 1 to n*n appear exactly once in the grid
constraint
  forall(r in 1..n, c in 1..n) (
    x[r,c] in 1..n*n
  ) /\
  alldifferent([x[r,c] | r,c in 1..n]);

% Link x and pos_row, pos_col
constraint
  forall(r in 1..n, c in 1..n) (
    let { var int: v = x[r,c] } in
      pos_row[v] = r /\ pos_col[v] = c
  );

% Movement constraints between consecutive numbers v and v+1
% For v in 1..n*n-1:
% If next number is placed vertically or horizontally:
%   distance must be exactly 3 squares away (gap of 2 squares)
% If next number is placed diagonally:
%   distance must be exactly 2 squares away (gap of 1 square)
%
% We define dx = abs(pos_row[v+1] - pos_row[v])
% and dy = abs(pos_col[v+1] - pos_col[v])
%
% Then:
%   Either (dx = 3 and dy = 0) or (dx = 0 and dy = 3)  (horizontal or vertical)
%   Or (dx = 2 and dy = 2)                              (diagonal)

constraint
  forall(v in 1..n*n-1) (
    let {
      var int: dx = abs(pos_row[v+1] - pos_row[v]),
      var int: dy = abs(pos_col[v+1] - pos_col[v])
    } in
      (dx = 3 /\ dy = 0) \/
      (dx = 0 /\ dy = 3) \/
      (dx = 2 /\ dy = 2)
  );

solve satisfy;

output [
  "{",
  "\"x\": [",
  join(",\n", [
    "[" ++ join(", ", [show(x[r,c]) | c in 1..n]) ++ "]"
    | r in 1..n
  ]),
  "]",
  "}"
];
```

