% Include necessary library for global constraints
include "globals.mzn";

% Input data
array[1..9] of int: ratings = [2, 3, 4, 4, 4, 2, 1, 3, 4];
int: n = length(ratings);

% Decision variables: candies given to each child
array[1..n] of var 1..n: candies;

% Constraints:
% 1. Each child gets at least 1 candy (already ensured by domain)
% 2. If a child has a higher rating than the immediate neighbor,
%    then that child must get more candies than that neighbor.
constraint
  forall(i in 1..n-1) (
    if ratings[i] > ratings[i+1] then
      candies[i] > candies[i+1]
    else if ratings[i] < ratings[i+1] then
      candies[i] < candies[i+1]
    else
      true
    endif
  );

% Objective: minimize total candies
var int: z = sum(i in 1..n)(candies[i]);
solve minimize z;

output [
  "{",
  "\"z\": " ++ show(z),
  "}"
];
```

