include "globals.mzn";

% We have 12 positions on the clock, numbered 1 to 12.
% The numbers 1 to 12 must be arranged on these positions.
% The first position must be 12.

int: n = 12;
set of int: POS = 1..n;
set of int: NUM = 1..n;

% Decision variable: x[p] is the number at position p on the clock
array[POS] of var NUM: x;

% Constraint: all numbers are distinct
constraint
    all_different(x);

% Constraint: the first number is 12
constraint
    x[1] = 12;

% We want to minimize the maximum sum of any triplet of adjacent numbers.
% Adjacent triplets are (p, p+1, p+2) modulo 12.
% Define an array of sums of triplets
array[POS] of var int: triplet_sums;

constraint
    forall(p in POS) (
        let {
            int: p1 = p,
            int: p2 = if p+1 <= n then p+1 else p+1 - n endif,
            int: p3 = if p+2 <= n then p+2 else p+2 - n endif
        } in
        triplet_sums[p] = x[p1] + x[p2] + x[p3]
    );

% Define the maximum sum of any triplet
var int: max_sum = max(triplet_sums);

% We want to minimize max_sum
solve minimize max_sum;

output [
    "{",
    "\"x\": [" ++ join(", ", [show(x[p]) | p in POS]) ++ "]",
    "}"
];
```

