% Include necessary library for global constraints
include "globals.mzn";

% Input data
int: num_moves = 3;  % Number of moves allowed
array[1..3] of int: init = [1, 0, 1];  % Initial configuration: 1=heads, 0=tails

% Decision variables
% steps[m] = index of coin flipped at move m (1-based indexing)
array[1..num_moves] of var 1..3: steps;

% State of coins after each move: state[m, c] = coin c state after move m
array[0..num_moves, 1..3] of var 0..1: state;

% Initial state is given
constraint forall(c in 1..3) (
    state[0,c] = init[c]
);

% State transition constraints: flipping one coin per move
constraint forall(m in 1..num_moves) (
    forall(c in 1..3) (
        if c == steps[m] then
            state[m,c] = 1 - state[m-1,c]  % flip the coin
        else
            state[m,c] = state[m-1,c]      % unchanged
        endif
    )
);

% Final state must be all heads (1) or all tails (0)
constraint
    (forall(c in 1..3)(state[num_moves,c] = 1)) \/
    (forall(c in 1..3)(state[num_moves,c] = 0));

solve satisfy;

output [
    "{",
    "\"steps\": [" ++ join(", ", [show(steps[m]) | m in 1..num_moves]) ++ "]",
    "}"
];
